def transform(grid):
    n = len(grid[0])
    center = next(i for i, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            left, right = center - r, center + r
            out[r][left] = 2
            out[r][right] = 2
        if r >= 3:
            for c in range(n):
                if (c - r - center) % 4 == 0:
                    if r > center or center - r < c < center + r:
                        out[r][c] = 1
    return out
